ALTER TABLE pending_invoices ADD COLUMN IF NOT EXISTS posbox_device_id uuid;
CREATE TABLE IF NOT EXISTS partner_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, handle text NOT NULL UNIQUE, region text NOT NULL, status text NOT NULL DEFAULT 'pending', password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS partner_claim_codes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES partner_accounts(id), code_hash text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS posbox_devices_attribution (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), device_id uuid NOT NULL, partner_id uuid REFERENCES partner_accounts(id), mac text NOT NULL UNIQUE, first_seen_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), conflict_alert text);
CREATE TABLE IF NOT EXISTS partner_earnings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES partner_accounts(id), device_id uuid, payment_hash text NOT NULL UNIQUE, amount_sats integer NOT NULL, fee_share_sats integer NOT NULL, payout_state text NOT NULL DEFAULT 'accrued', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS partner_payouts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES partner_accounts(id), amount_sats integer NOT NULL, state text NOT NULL DEFAULT 'queued', created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO partner_accounts (name,handle,region,status,password_hash) VALUES ('Johannesburg','johannesburg','South Africa','active','DISABLED_SEED'),('Thailand','thailand','Thailand','active','DISABLED_SEED'),('satoshi.si','satoshi-si','Europe','pending','DISABLED_SEED') ON CONFLICT (handle) DO NOTHING;
GRANT SELECT,INSERT,UPDATE ON partner_accounts,partner_claim_codes,posbox_devices_attribution,partner_earnings,partner_payouts TO openln;
CREATE OR REPLACE FUNCTION prevent_partner_earning_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'partner_earnings is append-only'; END; $$;
DROP TRIGGER IF EXISTS partner_earnings_no_mutation ON partner_earnings;
CREATE TRIGGER partner_earnings_no_mutation BEFORE UPDATE OR DELETE ON partner_earnings FOR EACH ROW EXECUTE FUNCTION prevent_partner_earning_mutation();
